  async function request(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(url,{headers:{Accept:"application/json"},signal:controller.signal});if(!r.ok){const error=new Error(`${r.status} ${r.statusText}`);error.status=r.status;throw error}return await r.json()}catch(error){if(error.name==="AbortError")throw window.FieldworkLocale.error("读取超时（15 秒），请重试","Read timed out after 15 seconds. Retry.");throw error}finally{clearTimeout(timer)}}
  async function post(url,payload){const r=await fetch(url,{method:"POST",headers:{Accept:"application/json","Content-Type":"application/json"},body:JSON.stringify(payload)});if(!r.ok){let message=`${r.status} ${r.statusText}`;try{const data=await r.json();message=typeof data.detail==="string"?data.detail:message}catch{}throw new Error(message)}return r.json()}
  async function optional(url){try{return{ok:true,data:await request(url)}}catch(error){return{ok:false,error}}}
  function toast(text){const el=$("#toast");localizedText(el,()=>text);el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}
