  function skeleton(){return `<div class="skeleton-grid"><i></i><i></i><i></i></div>`}
  function page(items,key,size){const pages=Math.max(1,Math.ceil(items.length/size));state.page[key]=Math.min(state.page[key],pages);const start=(state.page[key]-1)*size;return{items:items.slice(start,start+size),pages,total:items.length}}
