  function closeMobileNavigation(restoreFocus=true){if(!$("#sidebar").classList.contains("open"))return;$("#sidebar").classList.remove("open");$("#sidebar").removeAttribute("role");$("#sidebar").removeAttribute("aria-modal");$("#mobileNavBackdrop").hidden=true;$("#content").inert=false;document.body.classList.remove("mobile-nav-open");$("#mobileMenu").setAttribute("aria-expanded","false");if(restoreFocus)$("#mobileMenu").focus()}
