    localizedText($("#lastUpdated"),()=>(campaignsOk&&tasksOk&&findingsOk?t("同步于 ","Updated at "):t("部分数据同步于 ","Partially updated at "))+(state.syncedAt||new Date()).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}));
    const ep=page(state.engagements,"engagements",6);
    $("#engagementList").innerHTML=!campaignsOk?empty(t("Campaign 数据不可用","Campaign data unavailable"),t("项目接口读取失败，请重试。","Could not load projects. Please retry."),"unavailable"):ep.total?ep.items.map(x=>row(x.name||x.target||x.id,x.target||x.id,x.status||"draft",x)).join(""):empty(t("还没有 Campaign","No campaigns yet"),t("从新建研究开始创建已授权项目。","Choose New research to create an authorized project."));
    pager("#engagementPager","engagements",ep,renderCampaign);
    const tp=page(state.tasks,"tasks",6);
    $("#taskList").innerHTML=!tasksOk?empty(t("任务数据不可用","Task data unavailable"),t("Task Center 读取失败，请重试。","Could not read the task center. Please retry."),"unavailable"):tp.total?tp.items.map(x=>row(x.objective||x.current_stage||x.id,x.last_event||x.next_action||x.engagement_id,x.status,x)).join(""):empty(t("当前没有执行任务","No execution tasks"),t("确认 Scope 并创建任务后会显示在这里。","Tasks appear here after scope confirmation and task creation."));
    pager("#taskPager","tasks",tp,renderCampaign);
