    const partial=!(tasksOk&&findingsOk);
    localizedText($("#attentionCount"),()=>partial?t("部分数据","Partial data"):`${attention.length}${t(" 项"," items")}`);
    $("#attentionList").innerHTML=(partial?`<p class="trust-note">${!tasksOk?t("任务状态不可用。","Task status unavailable. "):""}${!findingsOk?t("候选数据不可用。","Candidate data unavailable. "):""}${t("当前列表可能不完整。","This list may be incomplete.")}</p>`:"")+(attention.length?attention.slice(0,6).map(x=>row(x.title||(x.stalled?t("任务疑似停滞","Task may be stalled"):t("需要人工处理","Needs review")),text(x.next_action||x.last_event||x.id),x.status||"candidate",x)).join(""):partial?empty(t("无法确认待办总量","Cannot determine total pending items"),t("恢复数据连接后再判断是否为空。","Restore the data connection before concluding that the queue is empty."),"unavailable"):empty(t("暂无人工待办","No pending review"),t("阻塞、失败和待复验候选会集中显示。","Blocked tasks, failures, and candidates awaiting verification appear here.")));
