    host.innerHTML=`<div class="metrics compact">${metrics}</div><article class="panel"><div class="task-toolbar"><label>${t("搜索假设","Search hypotheses")}<input id="hypothesisSearch" type="search" value="${esc(state.hypothesisQuery)}" placeholder="${t("ID、陈述、类别或下一步","ID, statement, category, or next step")}"></label><label>${t("状态","Status")}<select id="hypothesisStatus"><option value="all">${t("全部状态","All statuses")}</option>${statuses.map(s=>`<option value="${esc(s)}" ${state.hypothesisStatus===s?"selected":""}>${esc(statusText(s))}</option>`).join("")}</select></label></div><p class="trust-note">${t("优先级不等于成立概率；当前 API 未提供独立 Confidence、Agent 数或 Verifier 字段，因此不推断这些值。","Priority is not the probability that a claim is true. This API does not provide independent confidence, agent counts, or verifier fields; those values are not inferred.")}</p>${p.total?table(["ID",t("陈述 / 下一步","Statement / next step"),"Domain",t("状态","Status"),"Confidence",t("证据","Evidence"),t("反证","Counterevidence"),"Agent","Verifier",t("更新时间","Updated at"),t("操作","Action")],rows):empty(all.length?t("没有匹配的假设","No matching hypotheses"):t("当前 Campaign 尚无假设","No hypotheses for this campaign"),all.length?t("调整搜索或状态条件。","Adjust the search or status filter."):t("使用“新建假设”记录待验证判断。","Choose New hypothesis to record a claim for verification.")) }<div id="hypothesisPager" class="pager"></div></article>`;
